def transform(grid):
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != background}
    components = []
    while remaining:
        seed = min(remaining)
        remaining.remove(seed)
        stack = [seed]
        component = []
        while stack:
            r, c = stack.pop()
            component.append((r, c))
            for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if p in remaining:
                    remaining.remove(p)
                    stack.append(p)
        components.append(component)
    result = []
    for component in sorted(components, key=lambda cells: min(cells)):
        order = []
        counts = Counter()
        for r, c in sorted(component):
            color = grid[r][c]
            if color not in counts:
                order.append(color)
            counts[color] += 1
        for color in order:
            result.extend([[color]] * counts[color])
    return result
