def transform(grid):
    from collections import Counter, deque
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    foreground = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    groups = []
    while foreground:
        first = min(foreground)
        q = deque([first])
        foreground.remove(first)
        group = []
        while q:
            p = q.popleft()
            group.append(p)
            r, c = p
            for n in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if n in foreground:
                    foreground.remove(n)
                    q.append(n)
        groups.append(group)
    group = max(groups, key=len)
    out = []
    for r, c in sorted(group):
        color = grid[r][c]
        if out and out[-1][0] == color:
            out[-1].append(color)
        else:
            out.append([color])
    return [[run[0]] for run in out for _ in run]
