def transform(grid):
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # The largest contiguous trail gives the colors and their order; its
    # endpoint at each stage determines the lengths of the output runs.
    h, w = len(grid), len(grid[0])
    pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    # Find the longest simple path through 4-connected same/adjacent cells.
    # For these snake-like inputs, a degree-1 endpoint starts the trail.
    adj = {p: [] for p in pts}
    for r, c in pts:
        for q in ((r+1,c),(r,c+1)):
            if q in pts:
                adj[(r,c)].append(q)
                adj[q].append((r,c))
    starts = sorted(pts, key=lambda p: (len(adj[p]), p))
    best = []
    def dfs(p, path, seen):
        nonlocal best
        if len(path) > len(best):
            best = path[:]
        for q in adj[p]:
            if q not in seen:
                seen.add(q)
                path.append(q)
                dfs(q, path, seen)
                path.pop()
                seen.remove(q)
    for s in starts[:2]:
        dfs(s, [s], {s})
    out = []
    for r, c in best:
        out.append([grid[r][c]])
    return out
